insert into public.places (id, icon, category, sort_order, floor, title, summary, text) values
  ('gate', '🚩', 'palace', 1, '{"vi":"Sân trước & cổng chính","en":"Front lawn & main gate","zh":"前庭与正门","ja":"前庭と正門","ko":"앞마당과 정문"}'::jsonb, '{"vi":"Cổng chính & xe tăng","en":"Main gate & tanks","zh":"正门与坦克","ja":"正門と戦車","ko":"정문과 탱크"}'::jsonb, '{"vi":"Cổng nơi xe tăng Quân giải phóng tiến vào ngày 30/4/1975.","en":"The gate the Liberation Army tanks drove through on 30 April 1975.","zh":"1975年4月30日解放军坦克冲入的大门。","ja":"1975年4月30日に解放軍の戦車が突入した門。","ko":"1975년 4월 30일 해방군 탱크가 진입한 문."}'::jsonb, '{"vi":"Bạn đang đứng trước cổng chính của Dinh Độc Lập. Trưa ngày 30 tháng 4 năm 1975, xe tăng 390 của Quân giải phóng húc đổ cổng này, cùng xe tăng 843 tiến vào khuôn viên Dinh. Sự kiện đó đánh dấu thời khắc kết thúc chiến tranh và thống nhất đất nước. Ngày nay, hai chiếc xe tăng được trưng bày trong khuôn viên để nhắc lại khoảnh khắc lịch sử ấy.","en":"You are standing at the main gate of Independence Palace. At midday on 30 April 1975, tank 390 of the Liberation Army crashed through this gate, and with tank 843 entered the grounds. That moment marked the end of the war and the reunification of the country. Today, two tanks are displayed in the grounds to recall that historic moment.","zh":"您现在站在独立宫的正门前。1975年4月30日中午，解放军的390号坦克撞开了这道大门，并与843号坦克一起冲入宫内。这一刻标志着战争的结束和国家的统一。如今，两辆坦克陈列在院内，让人们回想那个历史时刻。","ja":"ここは独立宮殿の正門前です。1975年4月30日の正午、解放軍の戦車390号がこの門を突き破り、843号とともに敷地内に進入しました。この出来事は戦争の終結と国家統一の瞬間を示しています。現在、敷地内には2両の戦車が展示され、歴史的な瞬間を伝えています。","ko":"지금 독립궁의 정문 앞에 서 계십니다. 1975년 4월 30일 정오, 해방군의 390호 탱크가 이 문을 부수고 843호 탱크와 함께 궁 안으로 진입했습니다. 이 순간은 전쟁의 종결과 나라의 통일을 상징합니다. 오늘날 경내에는 탱크 두 대가 전시되어 그 역사적인 순간을 전하고 있습니다."}'::jsonb),
  ('history', '🏛️', 'palace', 2, '{"vi":"Sảnh chính","en":"Main lobby","zh":"主厅","ja":"メインロビー","ko":"중앙 로비"}'::jsonb, '{"vi":"Lịch sử Dinh","en":"History of the Palace","zh":"宫殿历史","ja":"宮殿の歴史","ko":"궁의 역사"}'::jsonb, '{"vi":"Từ Dinh Norodom (1868) đến Dinh Độc Lập (1966).","en":"From Norodom Palace (1868) to Independence Palace (1966).","zh":"从诺罗敦宫（1868年）到独立宫（1966年）。","ja":"ノロドム宮殿（1868年）から独立宮殿（1966年）まで。","ko":"노로돔 궁(1868)에서 독립궁(1966)까지."}'::jsonb, '{"vi":"Nơi đây từng là Dinh Norodom, xây dựng từ năm 1868 làm nơi ở của Toàn quyền Pháp. Ngày 27 tháng 2 năm 1962, dinh cũ bị máy bay ném bom hư hại nặng. Kiến trúc sư Ngô Viết Thụ thiết kế công trình mới, hoàn thành năm 1966 và được đặt tên là Dinh Độc Lập. Sau năm 1975, nơi này được gọi là Hội trường Thống Nhất.","en":"This site was once Norodom Palace, built from 1868 as the residence of the French governor. On 27 February 1962, the old palace was heavily damaged in an air attack. Architect Ngo Viet Thu designed the new building, completed in 1966 and named Independence Palace. After 1975 it became known as Reunification Hall.","zh":"这里曾是诺罗敦宫，始建于1868年，是法国总督的官邸。1962年2月27日，旧宫在空袭中严重受损。建筑师吴越树设计了新建筑，于1966年竣工，命名为独立宫。1975年以后，这里被称为统一会堂。","ja":"この場所はかつてノロドム宮殿で、1868年にフランス総督の官邸として建てられました。1962年2月27日、旧宮殿は空爆で大きな被害を受けました。建築家ゴ・ヴィエト・トゥーが新しい建物を設計し、1966年に完成して独立宮殿と名付けられました。1975年以降は統一会堂と呼ばれています。","ko":"이곳은 1868년 프랑스 총독의 관저로 지어진 노로돔 궁이 있던 자리입니다. 1962년 2월 27일 옛 궁은 공습으로 크게 파손되었습니다. 건축가 응오비엣투가 새 건물을 설계하여 1966년에 완공했고 독립궁이라 이름 붙였습니다. 1975년 이후에는 통일회관이라 불립니다."}'::jsonb),
  ('architecture', '📐', 'palace', 3, '{"vi":"Mặt tiền & tổng thể","en":"Facade & overall design","zh":"立面与整体设计","ja":"ファサードと全体設計","ko":"정면과 전체 설계"}'::jsonb, '{"vi":"Kiến trúc Ngô Viết Thụ","en":"Architecture by Ngo Viet Thu","zh":"吴越树的建筑设计","ja":"ゴ・ヴィエト・トゥーの建築","ko":"응오비엣투의 건축"}'::jsonb, '{"vi":"Công trình cao 26 m, khoảng 100 phòng, phong cách hiện đại pha nét Việt.","en":"26 m tall, about 100 rooms, modern style with Vietnamese touches.","zh":"高26米、约100个房间，现代风格融入越南元素。","ja":"高さ26m、約100室、ベトナムらしさを加えたモダン建築。","ko":"높이 26m, 약 100개 방, 베트남 색을 더한 현대 건축."}'::jsonb, '{"vi":"Công trình do kiến trúc sư Ngô Viết Thụ, người Việt đầu tiên đoạt giải Grand Prix de Rome, thiết kế. Tòa nhà cao 26 mét, diện tích xây dựng khoảng 4.500 mét vuông, tổng diện tích sử dụng khoảng 20.000 mét vuông. Dinh có hầm, tầng trệt, ba tầng chính, hai tầng lửng, sân thượng và khoảng một trăm phòng. Lớp lam che nắng ở mặt tiền gợi hình khóm tre, thể hiện phong cách hiện đại pha nét truyền thống Việt Nam.","en":"The building was designed by Ngo Viet Thu, the first Vietnamese to win the Grand Prix de Rome. It stands 26 metres tall, with a footprint of about 4,500 square metres and about 20,000 square metres of usable floor space. The palace has a basement, a ground floor, three main floors, two mezzanines, a rooftop and about one hundred rooms. The sun-shading screens on the facade recall clumps of bamboo, blending modern style with Vietnamese tradition.","zh":"这座建筑由吴越树设计，他是首位获得罗马大奖的越南人。建筑高26米，占地约4500平方米，使用面积约2万平方米。宫内有地下层、底层、三个主要楼层、两个夹层、屋顶和约一百个房间。立面的遮阳格栅让人联想到竹丛，体现了现代风格与越南传统的融合。","ja":"この建物は、ベトナム人として初めてローマ大賞を受賞したゴ・ヴィエト・トゥーの設計です。高さは26メートル、建築面積は約4,500平方メートル、延べ床面積は約2万平方メートルあります。地下、1階、主要3フロア、2つの中2階、屋上、約100の部屋があります。ファサードの日よけは竹林を思わせ、現代的なスタイルとベトナムの伝統を融合しています。","ko":"이 건물은 베트남인 최초로 로마 대상을 받은 응오비엣투가 설계했습니다. 높이 26미터, 건축 면적 약 4,500제곱미터, 사용 면적 약 2만 제곱미터입니다. 지하층, 1층, 주요 3개 층, 중이층 2개, 옥상과 약 100개의 방이 있습니다. 정면의 차양은 대나무 숲을 연상시키며 현대적 양식과 베트남 전통을 조화시켰습니다."}'::jsonb),
  ('credentials', '📜', 'palace', 4, '{"vi":"Khu tiếp tân & nghi lễ","en":"Reception & ceremonial area","zh":"接待与礼仪区","ja":"応接・儀礼エリア","ko":"접견·의전 구역"}'::jsonb, '{"vi":"Phòng Quốc thư","en":"Credentials Room","zh":"国书厅","ja":"信任状の間","ko":"신임장 접수실"}'::jsonb, '{"vi":"Nơi Tổng thống tiếp đại sứ trình quốc thư.","en":"Where the President received ambassadors'' credentials.","zh":"总统接受大使递交国书的地方。","ja":"大統領が大使から信任状を受けた部屋。","ko":"대통령이 대사의 신임장을 받던 방."}'::jsonb, '{"vi":"Đây là Phòng Quốc thư, nơi Tổng thống tiếp các đại sứ đến trình quốc thư. Không gian trang trọng với bàn ghế bọc lụa và những bức tranh sơn mài mang đậm phong cách Việt Nam. Hãy chú ý cách bố trí đối xứng, thể hiện tính nghi lễ của căn phòng.","en":"This is the Credentials Room, where the President received ambassadors presenting their credentials. The formal space features silk-upholstered furniture and lacquer paintings in a distinctly Vietnamese style. Notice the symmetrical layout, which reflects the ceremonial nature of the room.","zh":"这里是国书厅，总统在此接见前来递交国书的大使。庄重的空间里摆放着丝绸软包的桌椅和富有越南风格的漆画。请留意对称的布局，体现了这个房间的礼仪性质。","ja":"こちらは信任状の間で、大統領が信任状を提出する大使を迎えた部屋です。格式ある空間には、絹張りの家具とベトナムらしい漆絵が飾られています。左右対称の配置に、儀礼の場としての性格が表れています。","ko":"이곳은 신임장 접수실로, 대통령이 신임장을 제정하러 온 대사들을 맞이하던 방입니다. 격식 있는 공간에 비단으로 감싼 가구와 베트남 특유의 칠화가 놓여 있습니다. 대칭적인 배치에서 이 방의 의전적인 성격을 느낄 수 있습니다."}'::jsonb),
  ('reception', '🥂', 'palace', 5, '{"vi":"Khu tiếp tân & nghi lễ","en":"Reception & ceremonial area","zh":"接待与礼仪区","ja":"応接・儀礼エリア","ko":"접견·의전 구역"}'::jsonb, '{"vi":"Phòng khánh tiết","en":"Grand Reception Hall","zh":"大宴会厅","ja":"大広間","ko":"대연회장"}'::jsonb, '{"vi":"Không gian lớn cho lễ nghi và tiệc chiêu đãi.","en":"A grand space for ceremonies and state banquets.","zh":"举办典礼和国宴的宏大空间。","ja":"式典や晩餐会のための広い空間。","ko":"의식과 연회를 위한 웅장한 공간."}'::jsonb, '{"vi":"Phòng khánh tiết là không gian rộng lớn dành cho các buổi lễ và tiệc chiêu đãi lớn. Trần cao, đèn chùm và khoảng không thoáng tạo cảm giác uy nghi. Công trình được thiết kế để đón gió và ánh sáng tự nhiên, phù hợp với khí hậu nhiệt đới.","en":"The Grand Reception Hall is a large space for ceremonies and major banquets. High ceilings, chandeliers and open space create a sense of grandeur. The building was designed to welcome breezes and natural light, suited to the tropical climate.","zh":"大宴会厅是举办典礼和大型宴请的宽敞空间。高高的天花板、吊灯和开阔的空间营造出庄严的气氛。建筑设计注重通风和自然采光，适应热带气候。","ja":"大広間は式典や大規模な晩餐会のための広い空間です。高い天井、シャンデリア、開放的な空間が荘厳な雰囲気を生み出しています。建物は風と自然光を取り入れる設計で、熱帯の気候に合っています。","ko":"대연회장은 각종 의식과 대규모 연회를 위한 넓은 공간입니다. 높은 천장과 샹들리에, 탁 트인 공간이 웅장한 분위기를 자아냅니다. 건물은 바람과 자연광을 받아들이도록 설계되어 열대 기후에 잘 맞습니다."}'::jsonb),
  ('presidentRoom', '🪑', 'palace', 6, '{"vi":"Khu tiếp tân","en":"Reception wing","zh":"接待区","ja":"応接エリア","ko":"접견 구역"}'::jsonb, '{"vi":"Phòng tiếp khách của Tổng thống","en":"President''s Reception Room","zh":"总统会客厅","ja":"大統領の応接室","ko":"대통령 접견실"}'::jsonb, '{"vi":"Ghế Tổng thống đặt cao, tựa lưng là bức phù điêu lá cờ.","en":"The President''s chair sits higher, with a flag panel behind it.","zh":"总统座椅位置更高，身后是国旗造型的木板。","ja":"大統領の椅子は一段高く、背後に国旗を表す板があります。","ko":"대통령 의자는 더 높고 뒤에 국기를 상징하는 판이 있습니다."}'::jsonb, '{"vi":"Đây là nơi Tổng thống tiếp khách. Chiếc ghế của Tổng thống được đặt cao hơn, phía sau là tấm gỗ lớn tượng trưng cho lá cờ quốc gia. Hãy để ý các tay ghế: ghế của Tổng thống và khách cấp cao chạm đầu rồng, còn ghế của những người khác chạm đầu phượng và chữ Thọ. Cách bố trí này thể hiện rõ thứ bậc và nghi lễ.","en":"This is where the President received guests. His chair is set higher, with a large wooden panel behind it representing the national flag. Look at the armrests: chairs for the President and senior guests are carved with dragon heads, while the others have phoenix heads and the character for longevity. The arrangement clearly expresses rank and protocol.","zh":"这里是总统会客的地方。总统的座椅位置更高，身后是象征国旗的大木板。请留意扶手：总统和高级来宾的座椅雕刻龙头，其他人的座椅则雕刻凤头和寿字。这样的布置清楚地体现了等级与礼仪。","ja":"ここは大統領が来客を迎えた部屋です。大統領の椅子は一段高く、背後には国旗を表す大きな木の板があります。肘掛けにご注目ください。大統領と要人の椅子には龍の頭、その他の人の椅子には鳳凰の頭と寿の字が彫られています。この配置が序列と儀礼をはっきり示しています。","ko":"이곳은 대통령이 손님을 맞이하던 방입니다. 대통령의 의자는 더 높게 놓였고 뒤에는 국기를 상징하는 큰 목판이 있습니다. 팔걸이를 보세요. 대통령과 고위 인사의 의자에는 용머리가, 그 밖의 사람들 의자에는 봉황 머리와 수(壽) 자가 새겨져 있습니다. 이 배치는 서열과 의전을 분명히 보여 줍니다."}'::jsonb),
  ('cabinet', '🗂️', 'palace', 7, '{"vi":"Khu tiếp tân & làm việc","en":"Reception & working area","zh":"接待与办公区","ja":"応接・執務エリア","ko":"접견·집무 구역"}'::jsonb, '{"vi":"Phòng họp Nội các","en":"Cabinet Meeting Room","zh":"内阁会议室","ja":"閣議室","ko":"내각 회의실"}'::jsonb, '{"vi":"Phòng họp của Nội các và Hội đồng Bộ trưởng.","en":"Meeting room of the Cabinet and Council of Ministers.","zh":"内阁与部长会议的会议室。","ja":"内閣と閣僚会議が開かれた部屋。","ko":"내각과 각료회의가 열리던 회의실."}'::jsonb, '{"vi":"Đây là phòng họp Nội các, nơi diễn ra các cuộc họp của Hội đồng Bộ trưởng và Nội các chính quyền Sài Gòn. Chiếc bàn họp hình chữ nhật cùng hệ thống ghế xếp ngay ngắn cho thấy không khí làm việc chính thức. Căn phòng gắn với nhiều quyết định chính trị và quân sự của thời kỳ này.","en":"This is the Cabinet Meeting Room, where the Saigon government discussed important matters. The long rectangular table and neatly arranged chairs convey a formal working atmosphere. The room is linked to many political and military decisions of that period.","zh":"这里是内阁会议室，西贡政府在此商议重要事务。长方形会议桌和整齐排列的座椅体现出正式的办公氛围。这个房间与那一时期的许多政治和军事决策相关联。","ja":"こちらは閣議室で、サイゴン政府が重要事項を協議した場所です。長方形の会議卓と整然と並んだ椅子が、公式な執務の雰囲気を伝えています。この部屋は当時の多くの政治的・軍事的決定と結びついています。","ko":"이곳은 내각 회의실로, 사이공 정부가 중요한 사안을 논의하던 곳입니다. 긴 직사각형 탁자와 가지런한 의자에서 공식적인 업무 분위기가 느껴집니다. 이 방은 당시의 많은 정치·군사적 결정과 연결되어 있습니다."}'::jsonb),
  ('office', '🖋️', 'palace', 8, '{"vi":"Khu làm việc","en":"Office wing","zh":"办公区","ja":"執務エリア","ko":"집무 구역"}'::jsonb, '{"vi":"Phòng làm việc của Tổng thống","en":"President''s Office","zh":"总统办公室","ja":"大統領執務室","ko":"대통령 집무실"}'::jsonb, '{"vi":"Nơi Tổng thống Nguyễn Văn Thiệu làm việc và tiếp khách.","en":"Where President Nguyen Van Thieu worked and met visitors.","zh":"阮文绍总统办公和会客的地方。","ja":"グエン・ヴァン・ティエウ大統領が執務し来客と会った部屋。","ko":"응우옌반티에우 대통령이 업무를 보고 손님을 만나던 곳."}'::jsonb, '{"vi":"Đây là phòng làm việc của Tổng thống. Tổng thống Nguyễn Văn Thiệu và Thủ tướng Trần Văn Hương từng tiếp khách tại đây, trong đó có cuộc gặp ngày 25 tháng 9 năm 1968. Căn phòng cho thấy nơi điều hành công việc hằng ngày của người đứng đầu chính quyền Sài Gòn.","en":"This is the President''s office. President Nguyen Van Thieu and Prime Minister Tran Van Huong received visitors here, including a meeting on 25 September 1968. The room shows where the head of the Saigon government ran daily affairs.","zh":"这里是总统办公室。阮文绍总统和陈文香总理曾在此会见来宾，其中包括1968年9月25日的一次会晤。这个房间展示了西贡政府首脑处理日常事务的地方。","ja":"ここは大統領執務室です。グエン・ヴァン・ティエウ大統領とチャン・ヴァン・フオン首相がここで来客と会い、その中には1968年9月25日の会談も含まれます。サイゴン政府の首脳が日々の業務を行った場所です。","ko":"이곳은 대통령 집무실입니다. 응우옌반티에우 대통령과 쩐반흐엉 총리가 이곳에서 손님을 맞이했으며, 1968년 9월 25일의 회견도 그중 하나입니다. 사이공 정부 수반이 일상 업무를 보던 곳입니다."}'::jsonb),
  ('family', '🛋️', 'palace', 9, '{"vi":"Khu sinh hoạt gia đình","en":"Family quarters","zh":"家庭起居区","ja":"家族の居住区","ko":"가족 생활 구역"}'::jsonb, '{"vi":"Khu sinh hoạt & phòng chiếu phim","en":"Family quarters & cinema","zh":"起居区与放映室","ja":"居住区とシネマルーム","ko":"생활 구역과 영화실"}'::jsonb, '{"vi":"Không gian riêng của gia đình Tổng thống, có phòng chiếu phim.","en":"The presidential family''s private space, with a cinema room.","zh":"总统家属的私人空间，设有放映室。","ja":"大統領家族のプライベート空間。シネマルームがあります。","ko":"대통령 가족의 사적 공간으로 영화실이 있습니다."}'::jsonb, '{"vi":"Dinh được thiết kế vừa là nơi làm việc vừa là nơi ở của Tổng thống, nên có khu sinh hoạt riêng cho gia đình. Theo giới thiệu tham quan, khu này giữ nhiều đồ nội thất nguyên bản và có một phòng chiếu phim riêng. Không khí ở đây yên tĩnh và gần gũi hơn so với các phòng nghi lễ ở phía dưới.","en":"The palace was designed as both the President''s workplace and residence, so it has private quarters for his family. According to visitor guides, this area keeps much original furniture and includes a private cinema room. The atmosphere is quieter and more intimate than the ceremonial rooms below.","zh":"宫殿既是总统的办公场所，也是他的住所，因此设有家属的私人起居区。据参观介绍，这里保留了许多原始家具，并设有一间私人放映室。这里的氛围比楼下的礼仪厅更安静、更亲切。","ja":"宮殿は大統領の職場であり住まいでもあるよう設計されたため、家族のための居住区があります。見学案内によると、このエリアには当時の家具が多く残り、専用のシネマルームもあります。下の儀礼用の部屋よりも静かで親密な雰囲気です。","ko":"이 궁은 대통령의 집무 공간이자 거처로 설계되어 가족을 위한 생활 구역이 있습니다. 관람 안내에 따르면 이곳에는 당시의 가구가 많이 남아 있고 전용 영화실도 있습니다. 아래층의 의전용 방보다 조용하고 아늑한 분위기입니다."}'::jsonb),
  ('rooftop', '🚁', 'palace', 10, '{"vi":"Tầng thượng","en":"Rooftop","zh":"屋顶","ja":"屋上","ko":"옥상"}'::jsonb, '{"vi":"Sân thượng & trực thăng","en":"Rooftop & helicopter","zh":"屋顶与直升机","ja":"屋上とヘリコプター","ko":"옥상과 헬기"}'::jsonb, '{"vi":"Sân đỗ trực thăng và dấu vết vụ ném bom 8/4/1975.","en":"The helipad and traces of the 8 April 1975 bombing.","zh":"直升机停机坪与1975年4月8日轰炸的痕迹。","ja":"ヘリポートと1975年4月8日の爆撃の痕跡。","ko":"헬기장과 1975년 4월 8일 폭격의 흔적."}'::jsonb, '{"vi":"Tầng thượng có sân đỗ trực thăng, nơi hiện đang trưng bày một chiếc trực thăng. Từ đây, bạn có thể nhìn xuống khuôn viên rộng lớn và thành phố xung quanh. Trên mái còn dấu vết vụ ném bom ngày 8 tháng 4 năm 1975 của phi công Nguyễn Thành Trung; quả bom chỉ nổ một phần.","en":"The rooftop has a helipad, where a helicopter is now on display. From here you can look down on the broad grounds and the surrounding city. The roof also bears traces of the 8 April 1975 bombing by pilot Nguyen Thanh Trung; the bomb only partly exploded.","zh":"屋顶设有直升机停机坪，现在陈列着一架直升机。在这里可以俯瞰宽阔的院落和周围的城市。屋顶上还留有飞行员阮成忠1975年4月8日轰炸的痕迹，那枚炸弹只有部分爆炸。","ja":"屋上にはヘリポートがあり、現在はヘリコプターが展示されています。ここから広い敷地と周囲の街を見渡せます。屋上には、1975年4月8日にグエン・タイン・チュン操縦士が行った爆撃の痕跡も残っており、爆弾は一部しか爆発しませんでした。","ko":"옥상에는 헬기장이 있으며 현재 헬리콥터가 전시되어 있습니다. 이곳에서 넓은 경내와 주변 도시를 내려다볼 수 있습니다. 옥상에는 1975년 4월 8일 응우옌탄쭝 조종사의 폭격 흔적도 남아 있으며, 폭탄은 일부만 터졌습니다."}'::jsonb),
  ('bunker', '📡', 'palace', 11, '{"vi":"Tầng hầm","en":"Basement","zh":"地下层","ja":"地下","ko":"지하"}'::jsonb, '{"vi":"Hầm chỉ huy","en":"Command bunker","zh":"地下指挥所","ja":"地下司令室","ko":"지하 지휘소"}'::jsonb, '{"vi":"Hầm kiên cố với phòng tác chiến và thiết bị liên lạc.","en":"Fortified basement with operations room and radio gear.","zh":"设有作战室和通信设备的坚固地下层。","ja":"作戦室と通信設備のある堅固な地下階。","ko":"작전실과 통신 장비를 갖춘 견고한 지하층."}'::jsonb, '{"vi":"Bạn đang ở tầng hầm kiên cố, được xây với tường bê tông dày để chống bom đạn. Nơi đây có phòng tác chiến, hệ thống liên lạc và bản đồ quân sự. Không gian chật hẹp, ánh đèn lạnh tạo nên cảm giác rất khác so với các phòng tiếp tân phía trên.","en":"You are in the fortified basement, built with thick concrete walls to withstand bombing. It contains an operations room, communications equipment and military maps. The cramped space and cold lighting feel very different from the reception rooms above.","zh":"您现在位于坚固的地下层，用厚实的混凝土墙建造，可抵御轰炸。这里设有作战室、通信设备和军事地图。狭小的空间和冷色的灯光，与楼上的接待厅感觉截然不同。","ja":"ここは堅固な地下階で、爆撃に耐えるよう厚いコンクリートの壁で造られています。作戦室、通信設備、軍事地図があります。狭い空間と冷たい照明は、上階の応接室とはまったく違う雰囲気です。","ko":"지금 계신 곳은 폭격에 견디도록 두꺼운 콘크리트 벽으로 지은 견고한 지하층입니다. 작전실과 통신 장비, 군사 지도가 있습니다. 좁은 공간과 차가운 조명은 위층의 접견실과 사뭇 다른 느낌을 줍니다."}'::jsonb),
  ('garden', '🌳', 'palace', 12, '{"vi":"Vườn phía sau Dinh","en":"Gardens behind the palace","zh":"宫殿后花园","ja":"宮殿の裏庭","ko":"궁 뒤편 정원"}'::jsonb, '{"vi":"Khu vườn & máy bay F-5E","en":"Gardens & F-5E fighter","zh":"花园与F-5E战机","ja":"庭園とF-5E戦闘機","ko":"정원과 F-5E 전투기"}'::jsonb, '{"vi":"Khu vườn nhiều bóng cây, có trưng bày máy bay F-5E.","en":"Shaded gardens with an F-5E fighter on display.","zh":"绿荫成片的花园，陈列着一架F-5E战机。","ja":"木陰の庭園に、F-5E戦闘機が展示されています。","ko":"나무 그늘이 많은 정원에 F-5E 전투기가 전시되어 있습니다."}'::jsonb, '{"vi":"Phía sau Dinh là khu vườn nhiều bóng cây, thích hợp để đi dạo chậm. Tại đây có trưng bày một chiếc máy bay chiến đấu F-5E, cùng loại máy bay mà phi công Nguyễn Thành Trung đã lái khi ném bom xuống Dinh ngày 8 tháng 4 năm 1975. Khoảng xanh này tạo sự tương phản với những câu chuyện lịch sử nặng nề của công trình.","en":"Behind the palace lie shaded gardens, ideal for a slow walk. An F-5E fighter jet is on display here, the same type of aircraft that pilot Nguyen Thanh Trung flew when he bombed the palace on 8 April 1975. The greenery contrasts with the weighty history of the building.","zh":"宫殿后面是绿荫成片的花园，适合慢慢散步。这里陈列着一架F-5E战机，与飞行员阮成忠1975年4月8日轰炸宫殿时驾驶的是同一机型。这片绿色与建筑沉重的历史形成了对比。","ja":"宮殿の裏手には木陰の庭園が広がり、ゆっくり散策するのに向いています。ここにはF-5E戦闘機が展示されており、1975年4月8日にグエン・タイン・チュン操縦士が宮殿を爆撃した際と同じ機種です。緑の空間は、建物の重い歴史と対照的です。","ko":"궁 뒤편에는 나무 그늘이 많은 정원이 있어 천천히 산책하기 좋습니다. 이곳에는 F-5E 전투기가 전시되어 있는데, 1975년 4월 8일 응우옌탄쭝 조종사가 궁을 폭격할 때 몰았던 것과 같은 기종입니다. 푸른 공간은 건물의 무거운 역사와 대비를 이룹니다."}'::jsonb),
  ('vehicles', '🚙', 'palace', 13, '{"vi":"Khu trưng bày xe","en":"Vehicle display","zh":"车辆展区","ja":"車両展示","ko":"차량 전시"}'::jsonb, '{"vi":"Xe Jeep & xe Mercedes","en":"Jeep & Mercedes","zh":"吉普车与奔驰","ja":"ジープとメルセデス","ko":"지프와 메르세데스"}'::jsonb, '{"vi":"Chiếc Jeep chở ông Dương Văn Minh đến Đài phát thanh ngày 30/4/1975.","en":"The Jeep that took Duong Van Minh to the radio station on 30 April 1975.","zh":"1975年4月30日载杨文明前往广播电台的吉普车。","ja":"1975年4月30日にズオン・ヴァン・ミンをラジオ局へ運んだジープ。","ko":"1975년 4월 30일 즈엉반민을 방송국으로 태운 지프."}'::jsonb, '{"vi":"Tại đây trưng bày hai phương tiện gắn với lịch sử Dinh. Chiếc Jeep M151A2 đã chở Tổng thống Dương Văn Minh đến Đài phát thanh Sài Gòn ngày 30 tháng 4 năm 1975. Bên cạnh là chiếc Mercedes Benz mà Tổng thống Nguyễn Văn Thiệu từng sử dụng.","en":"Two vehicles tied to the palace''s history are displayed here. The M151A2 Jeep carried President Duong Van Minh to Saigon Radio on 30 April 1975. Beside it is the Mercedes Benz once used by President Nguyen Van Thieu.","zh":"这里陈列着两辆与宫殿历史相关的车。M151A2吉普车曾于1975年4月30日载着杨文明总统前往西贡广播电台。旁边是阮文绍总统曾使用的奔驰轿车。","ja":"ここには宮殿の歴史に関わる2台の車が展示されています。M151A2ジープは、1975年4月30日にズオン・ヴァン・ミン大統領をサイゴン放送局へ運びました。隣には、グエン・ヴァン・ティエウ大統領が使用したメルセデス・ベンツがあります。","ko":"이곳에는 궁의 역사와 관련된 차량 두 대가 전시되어 있습니다. M151A2 지프는 1975년 4월 30일 즈엉반민 대통령을 사이공 방송국으로 태웠습니다. 그 옆에는 응우옌반티에우 대통령이 사용했던 메르세데스 벤츠가 있습니다."}'::jsonb),
  ('exhibition', '🏺', 'palace', 14, '{"vi":"Nhà trưng bày","en":"Exhibition house","zh":"展览馆","ja":"展示館","ko":"전시관"}'::jsonb, '{"vi":"Nhà trưng bày","en":"Exhibition House","zh":"展览馆","ja":"展示館","ko":"전시관"}'::jsonb, '{"vi":"Trưng bày \"Từ Dinh Norodom đến Dinh Độc Lập 1868–1966\".","en":"The permanent exhibition \"From Norodom Palace to Independence Palace, 1868–1966\".","zh":"常设展览“从诺罗敦宫到独立宫（1868—1966）”。","ja":"常設展「ノロドム宮殿から独立宮殿へ 1868〜1966」。","ko":"상설전 ''노로돔 궁에서 독립궁까지, 1868–1966''."}'::jsonb, '{"vi":"Nhà trưng bày là tòa nhà riêng trong khuôn viên, giới thiệu chuyên đề từ Dinh Norodom đến Dinh Độc Lập, giai đoạn 1868 đến 1966, với hàng nghìn hiện vật. Bạn nên dành khoảng ba mươi đến bốn mươi lăm phút để xem. Đây là nơi hiểu rõ nhất quá trình hình thành và thay đổi của công trình.","en":"The Exhibition House is a separate building in the grounds presenting the story from Norodom Palace to Independence Palace, 1868 to 1966, with thousands of objects. Allow around thirty to forty-five minutes. It is the best place to understand how the building took shape and changed.","zh":"展览馆是院内的独立建筑，以1868年至1966年从诺罗敦宫到独立宫为主题，展出数千件文物。建议预留三十到四十五分钟参观。这里最能帮助您了解建筑的形成和演变。","ja":"展示館は敷地内の独立した建物で、1868年から1966年までのノロドム宮殿から独立宮殿への歩みを、数千点の展示品で紹介しています。見学には30〜45分ほどかかります。建物の成り立ちと変遷を理解するのに最適な場所です。","ko":"전시관은 경내의 별도 건물로, 1868년부터 1966년까지 노로돔 궁에서 독립궁에 이르는 과정을 수천 점의 유물로 소개합니다. 관람에는 30~45분 정도가 걸립니다. 건물이 만들어지고 변해 온 과정을 이해하기에 가장 좋은 곳입니다."}'::jsonb),
  ('reunification', '🕊️', 'palace', 15, '{"vi":"Khuôn viên","en":"Grounds","zh":"院内","ja":"敷地内","ko":"경내"}'::jsonb, '{"vi":"Hội trường Thống Nhất","en":"Reunification Hall","zh":"统一会堂","ja":"統一会堂","ko":"통일회관"}'::jsonb, '{"vi":"Cái tên Hội trường Thống Nhất và di tích quốc gia đặc biệt.","en":"The name Reunification Hall and its Special National Monument status.","zh":"统一会堂之名与国家特别遗迹的地位。","ja":"統一会堂という名と特別国家遺跡の指定。","ko":"통일회관이라는 이름과 특별 국가 유적 지정."}'::jsonb, '{"vi":"Sau ngày 30 tháng 4 năm 1975, Dinh Độc Lập được đổi tên thành Hội trường Thống Nhất, gắn với ý nghĩa đất nước đã liền một dải. Công trình được xếp hạng Di tích quốc gia đặc biệt năm 2009. Ngày nay, mỗi năm nơi đây đón rất nhiều du khách trong nước và quốc tế. Cảm ơn bạn đã lắng nghe.","en":"After 30 April 1975, Independence Palace was renamed Reunification Hall, reflecting a country made whole again. The site was designated a Special National Monument in 2009. Today it welcomes many domestic and international visitors every year. Thank you for listening.","zh":"1975年4月30日之后，独立宫更名为统一会堂，寓意国家重归统一。2009年，该建筑被列为国家特别遗迹。如今，每年都有大量国内外游客到访。感谢您的收听。","ja":"1975年4月30日の後、独立宮殿は統一会堂と改称され、国が再び一つになったことを表しています。2009年には特別国家遺跡に指定されました。現在も毎年多くの国内外の観光客が訪れています。ご清聴ありがとうございました。","ko":"1975년 4월 30일 이후 독립궁은 통일회관으로 이름이 바뀌었고, 나라가 다시 하나가 되었음을 뜻합니다. 2009년에는 특별 국가 유적으로 지정되었습니다. 오늘날에도 매년 많은 국내외 관광객이 이곳을 찾습니다. 들어 주셔서 감사합니다."}'::jsonb)
